export type StyleTone = 
/**  Capitals and full punctuation. */
"formal" | 
/**  Capitals and lighter punctuation. */
"casual" | 
/**  Lower case and lighter punctuation. */
"veryCasual" | 
/**  An exclamation mark to finish. */
"excited";

export type Theme = "system" | "light" | "dark";

export type Toast = Toast_Serialize | Toast_Deserialize;

/**  What a toast button does. The bar sends it back with the toast's id. */
export type ToastAction = 
/**  Transcribe a cancelled dictation after all. */
"undo" | 
/**  Transcribe a failed dictation again. */
"retry" | 
/**  Transcribe a failed cloud dictation on this PC. */
"useLocal" | 
/**  Always type into this app instead of pasting. */
"alwaysType" | "openModels" | "openLanguages" | "openProviders" | "openMicSettings";

export type ToastButton = {
	action: ToastAction,
	label: string,
};

export type ToastDismissed = number;

export type ToastShown = ToastShown_Serialize | ToastShown_Deserialize;

export type ToastShown_Deserialize = Toast_Deserialize;

export type ToastShown_Serialize = Toast_Serialize;

