/**  A speech-to-text service the user brought a key for. */
export type Transcription = Transcription_Serialize | Transcription_Deserialize;

/**  A speech-to-text service the user brought a key for. */
export type Transcription_Deserialize = {
	/**
	 *  The service that hears dictations in place of the model on this PC,
	 *  such as `groq`. `None` keeps them here. Languages sent to Sarvam
	 *  still go there.
	 */
	provider?: string | null,
	/**  The model to ask. `None` takes the service's suggestion. */
	model?: string | null,
	/**  The address of a server the user runs. `None` uses its usual one. */
	endpoint?: string | null,
};

/**  A speech-to-text service the user brought a key for. */
export type Transcription_Serialize = {
	/**
	 *  The service that hears dictations in place of the model on this PC,
	 *  such as `groq`. `None` keeps them here. Languages sent to Sarvam
	 *  still go there.
	 */
	provider: string | null,
	/**  The model to ask. `None` takes the service's suggestion. */
	model: string | null,
	/**  The address of a server the user runs. `None` uses its usual one. */
	endpoint: string | null,
};

export type Translation = 
/**  The text stays in the spoken language. */
"none" | 
/**  The model or Sarvam turns speech straight into English. */
"speech" | 
/**  The transcript is translated afterwards, which needs a provider. */
"text";

export type UpdateChanged = UpdateChanged_Serialize | UpdateChanged_Deserialize;

export type UpdateChanged_Deserialize = UpdateStatus_Deserialize;

export type UpdateChanged_Serialize = UpdateStatus_Serialize;

/**  Where updating is at, for the About page and the tray. */
export type UpdateStatus = UpdateStatus_Serialize | UpdateStatus_Deserialize;

/**  Where updating is at, for the About page and the tray. */
export type UpdateStatus_Deserialize = 
/**  Development builds don't update themselves. */
{ state: "unsupported" } | 
/**  Nothing has been checked yet. */
{ state: "unknown" } | { state: "checking" } | { state: "upToDate" } | { state: "available"; version: string; notes?: string | null } | 
/**  `percent` is missing when the server doesn't say how big the download is. */
{ state: "downloading"; version: string; percent?: number | null } | 
/**  The installer took over, and Joona is about to close. */
{ state: "installing"; version: string } | { state: "failed"; message: string };

/**  Where updating is at, for the About page and the tray. */
export type UpdateStatus_Serialize = 
/**  Development builds don't update themselves. */
{ state: "unsupported" } | 
/**  Nothing has been checked yet. */
{ state: "unknown" } | { state: "checking" } | { state: "upToDate" } | { state: "available"; version: string; notes: string | null } | 
/**  `percent` is missing when the server doesn't say how big the download is. */
{ state: "downloading"; version: string; percent: number | null } | 
/**  The installer took over, and Joona is about to close. */
{ state: "installing"; version: string } | { state: "failed"; message: string };

/**  Which engine build to run. The Vulkan build is an optional download. */
export type Variant = "cpu" | "vulkan";

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

type EventEmitTo<T> = [T] extends [null] ? (target: __TAURI_EVENT.EventTarget | string) => Promise<void> : (target: __TAURI_EVENT.EventTarget | string, payload: T) => Promise<void>;

function makeEvent<TListen, TEmit = TListen>(name: string, serialize?: (payload: TEmit) => unknown, deserialize?: (payload: any) => TListen) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<TListen>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: TEmit) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => __TAURI_EVENT.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<TListen>) => target.once(name, mapEvent(cb)),
        emit: ((payload: TEmit) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<TEmit>,
        emitTo: ((to: __TAURI_EVENT.EventTarget | string, payload: TEmit) => target.emitTo(to, name, mapPayload(payload)) as unknown) as EventEmitTo<TEmit>
    });

    return Object.assign(fn, base);
}
